def sigs(src):
    t = ast.parse(src)
    out = {}
    for n in ast.walk(t):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            args = n.args
            pos = [a.arg for a in args.posonlyargs + args.args]
            defaults = [ast.unparse(d) for d in args.defaults]
            kw = [(a.arg, ast.unparse(d) if d else None) for a, d in zip(args.kwonlyargs, args.kw_defaults)]
            out[n.name] = (pos, defaults, kw)
    return out

