for p in sorted(pathlib.Path('ledgerly').glob('*/*.py')):
    if p.name == '__init__.py' or p.parts[1] == '_gen':
        continue
    old = subprocess.run(['git', 'show', 'HEAD:' + str(p)], capture_output=True, text=True)
    if old.returncode:
